package com.gomgomapps.math.core;
import java.math.*;import java.util.*;import java.util.regex.*;
/** Six exact public representation conversions; selected finite supply is not a validity gate. */
public final class RepresentationConversions {
 private RepresentationConversions(){}
 public static final String FD="conversionFractionDecimal",FP="conversionFractionPercent",DF="conversionDecimalFraction",DP="conversionDecimalPercent",PF="conversionPercentFraction",PD="conversionPercentDecimal",VERSION="representation-conversions-v1";
 public static final List<String> IDS=List.of(FD,FP,DF,DP,PF,PD);
 public static final Set<Integer> SELECTED_DENOMINATORS=Set.of(2,4,5,8,10,20,25,50,100);
 public static final List<Catalog.Skill> SKILLS=List.of(skill(FD,"변환: 분수→소수"),skill(FP,"변환: 분수→백분율"),skill(DF,"변환: 소수→분수"),skill(DP,"변환: 소수→백분율"),skill(PF,"변환: 백분율→분수"),skill(PD,"변환: 백분율→소수"));
 private static Catalog.Skill skill(String id,String title){return new Catalog.Skill(id,title,6,1,1,"","representationConversion",100,"","같은 값을 분수·소수·백분율로 나타낸다.");}
 public static boolean supports(String id){return id!=null&&IDS.contains(id);}
 private static String source(String id){return id.equals(FD)||id.equals(FP)?"fraction":id.equals(DF)||id.equals(DP)?"decimal":"percent";}
 private static String target(String id){return id.equals(DF)||id.equals(PF)?"fraction":id.equals(FD)||id.equals(PD)?"decimal":"percent";}
 private static String name(String form){return form.equals("fraction")?"분수":form.equals("decimal")?"소수":"백분율";}
 private static String suffix(String target){return target.equals("fraction")?"을 기약분수로 나타내세요.":target.equals("decimal")?"을 소수로 나타내세요. 정확한 소수로 쓰세요. 순환소수는 반복되는 부분을 괄호로 표시하세요.":"을 백분율로 나타내세요. % 기호도 함께 쓰세요. 순환소수는 반복되는 부분을 괄호로 표시하세요.";}
 public static String prompt(String id,String raw){if(!supports(id))throw new IllegalArgumentException("Unknown representation conversion");return name(source(id))+" "+raw+suffix(target(id));}
 public record Givens(String raw,Rational value,String source,String target){}
 private static final Pattern FRACTION=Pattern.compile("([0-9]{1,20})/([0-9]{1,20})"),SOURCE_NUMBER=Pattern.compile("[0-9]{1,20}(?:\\.[0-9]{1,12}|\\.[0-9]{0,12}\\([0-9]{1,20}\\))?");
 public static Givens read(Question q){if(q==null||!supports(q.skillId)||q.prompt==null)return null;String source=source(q.skillId),target=target(q.skillId),prefix=name(source)+" ",end=suffix(target);if(!q.prompt.startsWith(prefix)||!q.prompt.endsWith(end))return null;String raw=q.prompt.substring(prefix.length(),q.prompt.length()-end.length());if(raw.length()>120)return null;Rational value;
  if(source.equals("fraction")){Matcher m=FRACTION.matcher(raw);if(!m.matches())return null;try{value=new Rational(new BigInteger(m.group(1)),new BigInteger(m.group(2)));}catch(RuntimeException invalid){return null;}}
  else{String number=source.equals("percent")&&raw.endsWith("%")?raw.substring(0,raw.length()-1).trim():raw;if(source.equals("percent")&&!raw.endsWith("%")||!SOURCE_NUMBER.matcher(number).matches())return null;value=sourceNumeric(number);if(value==null)return null;if(source.equals("percent"))value=value.div(Rational.of(100));}
  return new Givens(raw,value,source,target);
 }
 private static Rational sourceNumeric(String raw){return raw.contains(".")?decimalInput(raw):integerInput(raw);}
 public static Rational decimalInput(String raw){return FractionDecimalRecall.exactInput(raw);}
 public static Rational integerInput(String input){if(input==null||input.length()>120)return null;String raw=input.trim().replace('−','-');if(!raw.matches("[+-]?[0-9]+"))return null;try{return new Rational(new BigInteger(raw),BigInteger.ONE);}catch(RuntimeException invalid){return null;}}
 public static Rational percentInput(String input){if(input==null||input.length()>120)return null;String raw=input.trim();if(!raw.endsWith("%"))return null;String number=raw.substring(0,raw.length()-1).trim();return number.contains(".")?decimalInput(number):integerInput(number);}
 private static Rational fractionInput(String input){if(input==null||input.length()>120)return null;String raw=input.trim().replace('−','-');if(!raw.matches("[+-]?[0-9]+/[+-]?[0-9]+"))return null;String[] p=raw.split("/",-1);try{return new Rational(new BigInteger(p[0]),new BigInteger(p[1]));}catch(RuntimeException invalid){return null;}}
 private static Rational exactTarget(String expected){return expected!=null&&expected.contains("/")?fractionInput(expected):integerInput(expected);}
 public static boolean acceptsStep(String value,String expected,String marker){if(marker==null)return false;Rational actual=marker.equals("convDecimal")?decimalInput(value):marker.equals("convPercent")?percentInput(value):marker.equals("convInteger")?integerInput(value):null,target=exactTarget(expected);return actual!=null&&actual.equals(target);}
 public static boolean fractionTarget(Question q){Givens g=read(q);return g!=null&&g.target.equals("fraction");}
 public static int errorPart(Question q,String raw){Givens g=read(q);if(g==null||!g.target.equals("fraction")||fractionInput(raw)==null)return 0;String[] p=raw.trim().replace('−','-').split("/",-1);BigInteger n=new BigInteger(p[0]),d=new BigInteger(p[1]);if(n.equals(g.value.n)&&d.equals(g.value.d))return 0;if(d.equals(g.value.d))return 1;if(n.equals(g.value.n))return 2;return 0;}
 static Checker.Result check(Question q,List<String> answers){Givens g=read(q);if(g==null)return new Checker.Result(Checker.Status.INPUT_NEEDED,-1,"문제 확인 필요");if(answers==null||answers.size()!=1||answers.get(0)==null)return new Checker.Result(Checker.Status.INPUT_NEEDED,0,"답 입력 필요");String raw=answers.get(0);Rational actual;
  if(g.target.equals("fraction")){actual=fractionInput(raw);if(actual==null)return new Checker.Result(Checker.Status.INPUT_NEEDED,0,"분수 입력 확인 필요");if(!actual.equals(g.value))return new Checker.Result(Checker.Status.WRONG_ANSWER,0,"이 답 확인");String[] p=raw.trim().replace('−','-').split("/");if(!new BigInteger(p[0]).equals(g.value.n)||!new BigInteger(p[1]).equals(g.value.d))return new Checker.Result(Checker.Status.INPUT_NEEDED,0,"약분 필요");}
  else{if(g.target.equals("percent")&&sourceNumeric(raw.trim())!=null)return new Checker.Result(Checker.Status.INPUT_NEEDED,0,"백분율 기호 % 입력 필요");actual=g.target.equals("percent")?percentInput(raw):decimalInput(raw);if(actual==null)return new Checker.Result(Checker.Status.INPUT_NEEDED,0,g.target.equals("percent")?"백분율 입력 확인 필요":"정확한 소수 입력 확인 필요");Rational expected=g.target.equals("percent")?g.value.mul(Rational.of(100)):g.value;if(!actual.equals(expected))return new Checker.Result(Checker.Status.WRONG_ANSWER,0,"이 답 확인");}
  return new Checker.Result(Checker.Status.CORRECT,-1,"계산 확인 완료");
 }
 private static void step(StudyGuide h,String instruction,String before,Rational expected,String marker){h.step(instruction,before,"",expected.toString());h.frames.get(h.frames.size()-1).inputFormat=marker;}
 private static void choice(StudyGuide h,String correct){Map<String,String> choices=new LinkedHashMap<>();if(correct.equals("divide")){choices.put("divide","분자를 분모로 나눈다.");choices.put("multiply","분자와 분모를 곱한다.");choices.put("add","분자와 분모를 더한다.");}else if(correct.equals("fractionPercent")){choices.put("fractionPercent","분자를 분모로 나눈 뒤 100을 곱한다.");choices.put("divide100","분자를 분모로 나눈 뒤 100으로 나눈다.");choices.put("multiply","분자와 분모를 곱한다.");}else if(correct.equals("multiply100")||correct.equals("divide100")){choices.put("multiply100","수에 100을 곱한다.");choices.put("divide100","수를 100으로 나눈다.");choices.put("same","수를 그대로 쓴다.");}else{choices.put("finiteFraction","소수 자릿수에 맞는 분모를 쓰고 약분한다.");choices.put("recurringFraction","10의 거듭제곱의 차로 순환소수를 분수로 나타내고 약분한다.");choices.put("percentFraction","백분율의 수를 100으로 나누고 약분한다.");}h.choice("다른 표현으로 바꾸는 관계를 고르세요.",choices,correct);}
 public static StudyGuide guide(Question q){Givens g=read(q);if(g==null)return null;StudyGuide h=new StudyGuide().transfer(false);h.teachingVersion=VERSION;
  if(g.source.equals("fraction")){choice(h,g.target.equals("decimal")?"divide":"fractionPercent");String[] p=g.raw.split("/");step(h,"문제의 분자를 쓰세요.","분자 n = ",integerInput(p[0]),"convInteger");step(h,"문제의 분모를 쓰세요.","분모 d = ",integerInput(p[1]),"convInteger");step(h,"분자를 분모로 나누어 정확한 소수로 쓰세요.","소수 v = n ÷ d = ",g.value,"convDecimal");if(g.target.equals("percent"))step(h,"소수에 100을 곱하고 % 기호를 함께 쓰세요.","백분율 p = v × 100 = ",g.value.mul(Rational.of(100)),"convPercent");return h;}
  if(!g.target.equals("fraction")){boolean percent=g.source.equals("percent");choice(h,percent?"divide100":"multiply100");step(h,percent?"문제의 백분율을 기호와 함께 쓰세요.":"문제의 소수 값을 쓰세요.",percent?"백분율 p = ":"소수 v = ",percent?g.value.mul(Rational.of(100)):g.value,percent?"convPercent":"convDecimal");step(h,percent?"백분율의 수를 100으로 나누어 정확한 소수로 쓰세요.":"소수에 100을 곱하고 % 기호를 함께 쓰세요.",percent?"소수 v = p ÷ 100 = ":"백분율 p = v × 100 = ",percent?g.value:g.value.mul(Rational.of(100)),percent?"convDecimal":"convPercent");return h;}
  boolean percent=g.source.equals("percent");String number=percent?g.raw.substring(0,g.raw.length()-1).trim():g.raw;boolean recurring=number.contains("(");choice(h,percent?"percentFraction":recurring?"recurringFraction":"finiteFraction");step(h,percent?"문제의 백분율을 기호와 함께 쓰세요.":"문제의 소수 값을 쓰세요.",percent?"백분율 p = ":"소수 v = ",percent?g.value.mul(Rational.of(100)):g.value,percent?"convPercent":"convDecimal");
  String[] pieces=number.split("\\.",-1);String whole=pieces[0],fixed=pieces.length==1?"":pieces[1],cycle="";if(recurring){int at=fixed.indexOf('(');cycle=fixed.substring(at+1,fixed.length()-1);fixed=fixed.substring(0,at);}BigInteger a=BigInteger.TEN.pow(fixed.length()),b=recurring?BigInteger.TEN.pow(cycle.length()).subtract(BigInteger.ONE):BigInteger.ONE;BigInteger prefix=new BigInteger(whole).multiply(a).add(fixed.isEmpty()?BigInteger.ZERO:new BigInteger(fixed)),n=prefix.multiply(b).add(cycle.isEmpty()?BigInteger.ZERO:new BigInteger(cycle)),d=a.multiply(b).multiply(BigInteger.valueOf(percent?100:1));
  step(h,"고정된 소수 부분의 자릿수에 맞는 10의 거듭제곱을 쓰세요.","자리수 기준 A = 10^"+fixed.length()+" = ",new Rational(a,BigInteger.ONE),"convInteger");
  if(recurring)step(h,"반복되는 부분의 자릿수에 맞는 10의 거듭제곱에서 1을 빼세요.","순환 기준 B = 10^"+cycle.length()+" − 1 = ",new Rational(b,BigInteger.ONE),"convInteger");
  step(h,"약분 전 분자를 구하세요.",recurring?"분자 N = ("+whole+" × A + "+(fixed.isEmpty()?"0":fixed)+") × B + "+cycle+" = ":"분자 N = "+number+" × A = ",new Rational(n,BigInteger.ONE),"convInteger");
  step(h,"약분 전 분모를 구하세요.","분모 D = A"+(recurring?" × B":"")+(percent?" × 100":"")+" = ",new Rational(d,BigInteger.ONE),"convInteger");BigInteger gcd=n.gcd(d);step(h,"약분 전 분자와 분모의 최대공약수를 구하세요.","최대공약수 G = gcd(N, D) = ",new Rational(gcd,BigInteger.ONE),"convInteger");
  int numerator=h.frames.size();step(h,"분자를 최대공약수로 나누세요.","분자 n = N ÷ G = ",new Rational(g.value.n,BigInteger.ONE),"convInteger");int denominator=h.frames.size();step(h,"분모를 같은 최대공약수로 나누세요.","분모 d = D ÷ G = ",new Rational(g.value.d,BigInteger.ONE),"convInteger");h.fractionResult(numerator,denominator);return h;
 }
 public static Map<String,String> references(Question q,int stage,List<String> entries){StudyGuide h=guide(q);if(h==null||entries==null||stage<1||stage>=h.frames.size())return Map.of();Map<String,String> result=new LinkedHashMap<>();List<Integer> wanted=new ArrayList<>();if(h.resultNumeratorFrame!=null){int ni=h.resultNumeratorFrame,di=h.resultDenominatorFrame;if(stage==ni)wanted=List.of(ni-3,ni-1);else if(stage==di)wanted=List.of(ni-2,ni-1);else if(stage==ni-1)wanted=List.of(ni-3,ni-2);else for(int i=Math.max(1,stage-3);i<stage;i++)wanted.add(i);}else for(int i=Math.max(1,stage-2);i<stage;i++)wanted.add(i);for(int i:wanted)if(i<entries.size()&&new HelpPlan.Step(h.frames.get(i)).accepts(entries.get(i)))result.put(h.frames.get(i).before,entries.get(i));return result;}
 private static String finite(Rational value){String raw=value.decimalText();return raw.contains(".")?raw:raw+".0";}
 private static final Map<String,List<String>> SELECTED=selected();
 private static Map<String,List<String>> selected(){Map<String,List<String>> pools=new LinkedHashMap<>();for(String id:IDS){Set<String> raw=new LinkedHashSet<>();for(int d:new int[]{2,4,5,8,10,20,25,50,100})for(int n=0;n<=2*d;n++){Rational v=Rational.of(n,d);raw.add(source(id).equals("fraction")?n+"/"+d:source(id).equals("decimal")?finite(v):v.mul(Rational.of(100)).decimalText()+"%");}pools.put(id,List.copyOf(raw));}return Collections.unmodifiableMap(pools);}
 public static int domainSize(String id){return supports(id)?SELECTED.get(id).size():0;}
 static Question at(String id,int index){String raw=SELECTED.get(id).get(index);Question q=new Question(id,prompt(id,raw),"","");Givens g=read(q);q.kind=g.target.equals("fraction")?"number":g.target.equals("decimal")?"conversionDecimal":"conversionPercent";q.answerFormat=g.target.equals("fraction")?"fraction":q.kind;q.decimal=!g.target.equals("fraction");q.stepSupport=false;q.answers=new String[]{g.target.equals("fraction")?g.value.n+"/"+g.value.d:g.target.equals("decimal")?finite(g.value):g.value.mul(Rational.of(100)).decimalText()+"%"};q.studyGuide=guide(q);return q;}
 static Question next(String id,Random random,CurriculumLimits limits,Map<String,Integer> recent){return IndexedQuestionSupply.choose(domainSize(id),i->at(id,i),random,limits,recent);}
}
